#include <stdio.h>
#include <string.h>
#include <stdlib.h>

// Define a struct to hold the Roman numeral values
typedef struct {
    char *symbol;
    int value;
} RomanNumeral;

// Define the Roman numerals and their values
RomanNumeral romanNumerals[] = {
    {"I", 1},
    {"V", 5},
    {"X", 10},
    {"L", 50},
    {"C", 100},
    {"D", 500},
    {"M", 1000}
};

// Function to convert a Roman numeral to an integer
int romanToInt(char *s) {
    int result = 0;
    int i = 0;
    while (s[i] != '\0') {
        int current = 0;
        int next = 0;
        for (int j = 0; j < 7; j++) {
            if (strcmp(romanNumerals[j].symbol, &s[i]) == 0) {
                current = romanNumerals[j].value;
                break;
            }
        }
        if (i + 1 < strlen(s)) {
            for (int j = 0; j < 7; j++) {
                if (strcmp(romanNumerals[j].symbol, &s[i + 1]) == 0) {
                    next = romanNumerals[j].value;
                    break;
                }
            }
        }
        if (current < next) {
            result -= current;
        } else {
            result += current;
        }
        i++;
    }
    return result;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        printf("Usage: %s <Roman numeral>\n", argv[0]);
        return 1;
    }
    char *romanNumeral = argv[1];
    int result = romanToInt(romanNumeral);
    printf("%d\n", result);
    return 0;
}
